-- Bài 2
update public.lessons set summary = 'Tìm hiểu năng lượng của vật do chuyển động (động năng) và do vị trí so với mặt đất (thế năng trọng trường).' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'objective', 'Nêu được khái niệm động năng và thế năng trọng trường.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2) and x.content = 'Nêu được khái niệm động năng và thế năng trọng trường.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'objective', 'Viết được công thức tính động năng, thế năng và đơn vị của các đại lượng.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2) and x.content = 'Viết được công thức tính động năng, thế năng và đơn vị của các đại lượng.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'objective', 'Vận dụng công thức để tính động năng, thế năng trong một số trường hợp đơn giản.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2) and x.content = 'Vận dụng công thức để tính động năng, thế năng trong một số trường hợp đơn giản.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'requirement', 'Viết được biểu thức tính động năng của vật: Wđ = ½mv².', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2) and x.content = 'Viết được biểu thức tính động năng của vật: Wđ = ½mv².');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'requirement', 'Viết được biểu thức tính thế năng của vật ở gần mặt đất: Wt = Ph.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2) and x.content = 'Viết được biểu thức tính thế năng của vật ở gần mặt đất: Wt = Ph.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'knowledge', 'text', '1. Động năng', 'Năng lượng mà vật có được do chuyển động gọi là động năng.
Động năng của vật phụ thuộc vào khối lượng và tốc độ của vật: vật có khối lượng càng lớn, chuyển động càng nhanh thì động năng càng lớn.
Vật đứng yên thì động năng bằng 0.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2) and x.section = 'knowledge' and x.title = '1. Động năng');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'knowledge', 'formula', 'Công thức động năng', 'Wđ = ½·m·v²

Trong đó: Wđ – động năng (J); m – khối lượng của vật (kg); v – tốc độ của vật (m/s).', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2) and x.section = 'knowledge' and x.title = 'Công thức động năng');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'knowledge', 'text', '2. Thế năng trọng trường', 'Thế năng trọng trường (gọi tắt là thế năng) là năng lượng của một vật khi nó ở một độ cao nhất định so với mặt đất hoặc so với một vật được chọn làm gốc để tính độ cao.
Vật có trọng lượng càng lớn, ở càng cao thì thế năng trọng trường càng lớn. Giá trị của thế năng phụ thuộc vào gốc chọn để tính độ cao (gọi là gốc thế năng); người ta thường chọn mặt đất làm gốc, khi đó vật nằm trên mặt đất có thế năng bằng 0.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2) and x.section = 'knowledge' and x.title = '2. Thế năng trọng trường');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'knowledge', 'formula', 'Công thức thế năng trọng trường', 'Wt = P·h = 10·m·h

Trong đó: Wt – thế năng (J); P – trọng lượng của vật (N), P = 10·m; h – độ cao của vật so với mốc (m).', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2) and x.section = 'knowledge' and x.title = 'Công thức thế năng trọng trường');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'knowledge', 'example', 'Ví dụ', 'Một quả bóng khối lượng 0,5 kg bay với tốc độ 4 m/s ở độ cao 2 m so với mặt đất.
• Động năng: Wđ = ½·0,5·4² = 4 J.
• Thế năng: Wt = 10·0,5·2 = 10 J.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2) and x.section = 'knowledge' and x.title = 'Ví dụ');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'knowledge', 'text', 'Em có biết: các dạng thế năng khác', 'Ngoài thế năng trọng trường, trong thực tiễn vật còn có thể dự trữ năng lượng dưới dạng:
• Thế năng đàn hồi: xuất hiện khi một vật bị biến dạng đàn hồi (ví dụ cây cung đang bị kéo căng).
• Thế năng tĩnh điện: khi một điện tích đặt cạnh một điện tích khác, lực tương tác giữa các điện tích tạo ra thế năng của hệ điện tích.', 6, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2) and x.section = 'knowledge' and x.title = 'Em có biết: các dạng thế năng khác');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'experiment', 'text', 'Hoạt động SGK 2: Quan sát và giải thích (bài này không có thí nghiệm thực hành)', 'SGK Bài 2 gồm các hoạt động quan sát hình và câu hỏi, không có thí nghiệm thực hành. Ứng dụng cung cấp mô phỏng bổ trợ để minh hoạ.
• Hình 2.1 – búa đập vào thanh thép: búa có khối lượng lớn và chuyển động càng nhanh thì làm thanh thép biến dạng càng nhiều → động năng của búa càng lớn.
• Hình 2.2 – quả bóng bay tới rổ, ô tô đang di chuyển trên đường cao tốc, máy bay đang chuyển động trên bầu trời: vật nào có động năng lớn nhất? Giải thích.
• Hình 2.3 – sơ đồ đập thuỷ điện: giải thích vì sao khai thác được tối đa thế năng của nước khi đặt máy phát điện càng thấp so với mực nước hồ chứa.
• Câu hỏi: động năng của ô tô thay đổi thế nào nếu tốc độ tăng gấp đôi? Tính động năng của quả bóng đá 0,45 kg bay với tốc độ 10 m/s.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2) and x.section = 'experiment' and x.title = 'Hoạt động SGK 2: Quan sát và giải thích (bài này không có thí nghiệm thực hành)');

