update public.lessons set summary = 'Kính lúp là thấu kính hội tụ có tiêu cự ngắn giúp quan sát vật nhỏ; vận dụng tam giác đồng dạng giải bài tập thấu kính.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10) and summary is null;
