insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'objective', 'Viết được công thức cấu tạo và gọi tên được một số alkane đơn giản và thông dụng (C1 – C4).', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.content = 'Viết được công thức cấu tạo và gọi tên được một số alkane đơn giản và thông dụng (C1 – C4).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'objective', 'Viết được phương trình hoá học phản ứng đốt cháy của butane.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.content = 'Viết được phương trình hoá học phản ứng đốt cháy của butane.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'objective', 'Tiến hành được (hoặc quan sát qua liệu điện tử) thí nghiệm đốt cháy butane từ đó rút ra được tính chất hoá học cơ bản của alkane.', 4 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.content = 'Tiến hành được (hoặc quan sát qua liệu điện tử) thí nghiệm đốt cháy butane từ đó rút ra được tính chất hoá học cơ bản của alkane.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'objective', 'Trình bày được ứng dụng làm nhiên liệu của alkane trong thực tiễn.', 5 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.content = 'Trình bày được ứng dụng làm nhiên liệu của alkane trong thực tiễn.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'requirement', 'Nêu được ứng dụng làm nhiên liệu của các alkane.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.content = 'Nêu được ứng dụng làm nhiên liệu của các alkane.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'requirement', 'Sử dụng nhiên liệu như gas, xăng, dầu hoả tiết kiệm, hiệu quả.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.content = 'Sử dụng nhiên liệu như gas, xăng, dầu hoả tiết kiệm, hiệu quả.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'knowledge', 'text', '1. Khái niệm hydrocarbon, alkane', 'Một số hydrocarbon thông dụng (Hình 23.1): methane (có trong khí bùn ao), propane (có trong bình gas), ethylene (có trong khí sinh ra từ một số loại quả chín).
Hydrocarbon là loại hợp chất hữu cơ mà thành phần phân tử chỉ chứa các nguyên tố carbon và hydrogen. Hydrocarbon gồm nhiều loại khác nhau, như alkane, alkene,...
Alkane là những hydrocarbon mạch hở, phân tử chỉ chứa các liên kết đơn.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.section = 'knowledge' and x.title = '1. Khái niệm hydrocarbon, alkane');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'knowledge', 'text', '2. Cấu tạo phân tử và danh pháp của alkane (Bảng 23.1)', '• CH₄ – methane
• C₂H₆: CH₃–CH₃ – ethane
• C₃H₈: CH₃–CH₂–CH₃ – propane
• C₄H₁₀: CH₃–CH₂–CH₂–CH₃ – butane
Trong công thức phân tử của alkane, khi tăng thêm một nguyên tử carbon thì số nguyên tử hydrogen tăng thêm 2. Thành phần phân tử của các alkane hơn kém nhau một hay nhiều nhóm CH₂.
Alkane có công thức chung là CₙH₂ₙ₊₂ (n ≥ 1, n là số nguyên, dương).', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.section = 'knowledge' and x.title = '2. Cấu tạo phân tử và danh pháp của alkane (Bảng 23.1)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'knowledge', 'text', '3. Phản ứng cháy của alkane', 'Khi đốt cháy alkane trong không khí thu được sản phẩm chủ yếu là khí carbon dioxide và hơi nước:
C₃H₈ + 5O₂ →(t°) 3CO₂ + 4H₂O
C₄H₁₀ + 13/2 O₂ →(t°) 4CO₂ + 5H₂O
Phản ứng cháy của alkane toả nhiệt mạnh, vì vậy alkane được sử dụng làm nhiên liệu trong cuộc sống và trong sản xuất. Bên cạnh các sản phẩm trên, một phần alkane cháy không hoàn toàn tạo một lượng nhỏ sản phẩm là muội than (một dạng đơn chất của carbon) và carbon monoxide.
Các alkane khá bền ở điều kiện thường, chúng không phản ứng với acid, base và nhiều chất khác.
Mở rộng: công thức tổng quát CₙH₂ₙ₊₂ + (3n + 1)/2 O₂ →(t°) nCO₂ + (n + 1)H₂O.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.section = 'knowledge' and x.title = '3. Phản ứng cháy của alkane');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'knowledge', 'text', '4. Ứng dụng làm nhiên liệu của alkane (Bảng 23.2)', '• Nhiên liệu khí hoá lỏng: propane và butane dễ hoá lỏng, được dùng làm nhiên liệu cho bật lửa, bếp gas,...
• Nhiên liệu lỏng: các alkane ở trạng thái lỏng có thể dùng làm nhiên liệu dưới dạng xăng, dầu hoả, dầu diesel và nhiên liệu phản lực (jet fuel).
• Nhiên liệu rắn: các alkane ở trạng thái rắn có thể dùng làm nhiên liệu dưới dạng nến paraffin.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.section = 'knowledge' and x.title = '4. Ứng dụng làm nhiên liệu của alkane (Bảng 23.2)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'knowledge', 'example', 'Bài tập SGK', '• Phương trình cháy: CH₄ + 2O₂ →(t°) CO₂ + 2H₂O;  2C₂H₆ + 7O₂ →(t°) 4CO₂ + 6H₂O.
• Nhiệt lượng toả ra khi đốt cháy hoàn toàn 1 gam alkane (Bảng): methane 891/16 ≈ 55,7 kJ; ethane 1 561/30 ≈ 52,0 kJ; propane 2 220/44 ≈ 50,5 kJ; butane 2 878/58 ≈ 49,6 kJ. Đốt cháy 1 gam methane toả ra nhiều nhiệt nhất.
• Khí gas là hỗn hợp propane và butane có tỉ lệ thể tích 1 : 1 (tức tỉ lệ mol 1 : 1): 1 mol propane (44 g) và 1 mol butane (58 g) toả 2 220 + 2 878 = 5 098 kJ; đốt 1 kg khí gas toả ra khoảng 5 098/0,102 ≈ 5,0·10⁴ kJ.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.section = 'knowledge' and x.title = 'Bài tập SGK');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'experiment', 'text', 'Thí nghiệm: Tìm hiểu về phản ứng đốt cháy của butane (Hình 23.2)', 'Chuẩn bị: bật lửa gas (chứa butane) loại dài; bình tam giác bằng thuỷ tinh chịu nhiệt, sạch và khô, có nút; ống nghiệm đựng dung dịch nước vôi trong.
Tiến hành: đưa đầu bật lửa vào miệng bình tam giác úp ngược, đánh lửa bật gas và giữ lửa cháy cho tới khi thấy thành bình tam giác mờ đi thì dừng lại. Quay xuống bình tam giác lại và đổ nước vôi trong vào. Sau đó, đậy bình bằng nút và lắc đều.
Kết quả: thành bình mờ đi do có hơi nước tạo thành; nước vôi trong vẩn đục do có carbon dioxide tạo thành. Sản phẩm của phản ứng đốt cháy butane là carbon dioxide và hơi nước.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.section = 'experiment' and x.title = 'Thí nghiệm: Tìm hiểu về phản ứng đốt cháy của butane (Hình 23.2)');

-- Bài 24
update public.lessons set summary = 'Alkene là hydrocarbon mạch hở có một liên kết đôi C=C, công thức chung CₙH₂ₙ; ethylene cháy, cộng với bromine và trùng hợp thành polyethylene.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'objective', 'Nêu được khái niệm alkene.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.content = 'Nêu được khái niệm alkene.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'objective', 'Viết được công thức cấu tạo và nêu được tính chất vật lí của ethylene.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.content = 'Viết được công thức cấu tạo và nêu được tính chất vật lí của ethylene.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'objective', 'Trình bày được tính chất hoá học của ethylene (phản ứng cháy, phản ứng làm mất màu nước bromine, phản ứng trùng hợp). Viết được các phương trình hoá học xảy ra.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.content = 'Trình bày được tính chất hoá học của ethylene (phản ứng cháy, phản ứng làm mất màu nước bromine, phản ứng trùng hợp). Viết được các phương trình hoá học xảy ra.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'objective', 'Tiến hành được thí nghiệm (hoặc quan sát thí nghiệm) của ethylene: phản ứng đốt cháy, phản ứng làm mất màu nước bromine, quan sát và giải thích được tính chất hoá học cơ bản của alkene.', 4 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.content = 'Tiến hành được thí nghiệm (hoặc quan sát thí nghiệm) của ethylene: phản ứng đốt cháy, phản ứng làm mất màu nước bromine, quan sát và giải thích được tính chất hoá học cơ bản của alkene.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'objective', 'Trình bày được một số ứng dụng của ethylene: tổng hợp ethylic alcohol, tổng hợp nhựa polyethylene (PE).', 5 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.content = 'Trình bày được một số ứng dụng của ethylene: tổng hợp ethylic alcohol, tổng hợp nhựa polyethylene (PE).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'requirement', 'Nhận biết và lựa chọn được các sản phẩm làm từ nguyên liệu polyethylene và sử dụng chúng đúng cách để bảo vệ môi trường.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.content = 'Nhận biết và lựa chọn được các sản phẩm làm từ nguyên liệu polyethylene và sử dụng chúng đúng cách để bảo vệ môi trường.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'knowledge', 'text', '1. Khái niệm alkene', 'Cho công thức cấu tạo của một số alkene: CH₂=CH₂; CH₃–CH=CH₂; CH₃–CH=CH–CH₃. Điểm chung: phân tử có một liên kết đôi C=C.
Alkene là những hydrocarbon mạch hở, trong phân tử có một liên kết đôi C=C. Công thức chung của các alkene có dạng CₙH₂ₙ (với n ≥ 2, n là các số nguyên, dương).', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.section = 'knowledge' and x.title = '1. Khái niệm alkene');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'knowledge', 'text', '2. Ethylene: tính chất vật lí và cấu tạo phân tử', 'Tính chất vật lí: ethylene là chất khí ở điều kiện thường (hoá lỏng ở −104 °C và hoá rắn ở −169 °C), không màu, hầu như không tan trong nước, tan ít trong các dung môi hữu cơ như ethylic alcohol.
Cấu tạo phân tử: công thức phân tử của ethylene là C₂H₄; công thức cấu tạo là CH₂=CH₂. Phân tử ethylene có liên kết đôi C=C, trong đó có một liên kết kém bền, dễ bị phá vỡ trong các phản ứng hoá học.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.section = 'knowledge' and x.title = '2. Ethylene: tính chất vật lí và cấu tạo phân tử');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'knowledge', 'text', '3. Tính chất hoá học của ethylene', 'a) Phản ứng cháy: tương tự alkane, phản ứng đốt cháy alkene tạo ra sản phẩm chủ yếu là khí carbon dioxide và hơi nước. Phản ứng toả ra nhiều nhiệt:
C₂H₄ + 3O₂ →(t°) 2CO₂ + 2H₂O
b) Phản ứng cộng: khi ethylene phản ứng với nước bromine, phân tử bromine đã cộng hợp vào nối đôi C=C trong phân tử ethylene, liên kết kém bền trong liên kết đôi bị phá vỡ, tạo thành sản phẩm 1,2-dibromoethane:
CH₂=CH₂ + Br–Br → CH₂Br–CH₂Br   (viết gọn: C₂H₄ + Br₂ → C₂H₄Br₂)
Phản ứng trên gọi là phản ứng cộng.
c) Phản ứng trùng hợp: ở điều kiện thích hợp, các phân tử ethylene cộng hợp liên tiếp với nhau, liên kết kém bền trong liên kết đôi bị phá vỡ, tạo thành chất có khối lượng phân tử lớn:
nCH₂=CH₂ →(t°, p, xúc tác) (–CH₂–CH₂–)ₙ    (ethylene → polyethylene)
Phản ứng trên gọi là phản ứng trùng hợp. Polyethylene (nhựa PE) là chất rắn, không tan trong nước, không độc, được dùng để sản xuất túi đựng, màng bọc, chai, bình chứa,... Tuy nhiên, nhựa PE rất khó phân huỷ sinh học, có thể tồn tại bền trong môi trường hàng trăm năm, vì vậy cần giảm thiểu việc thải các sản phẩm làm từ nhựa PE ra ngoài môi trường.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.section = 'knowledge' and x.title = '3. Tính chất hoá học của ethylene');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'knowledge', 'text', '4. Ứng dụng của ethylene (Hình 24.2)', 'Ethylene là nguyên liệu quan trọng cho ngành công nghiệp sản xuất hoá chất và tổng hợp polymer: tổng hợp ethylic alcohol; tổng hợp acetic acid; sản xuất dung môi; kích thích quả mau chín; sản xuất polyethylene (PE), poly(vinyl chloride) (PVC).', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.section = 'knowledge' and x.title = '4. Ứng dụng của ethylene (Hình 24.2)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'knowledge', 'example', 'Câu hỏi SGK', 'Propylene là một alkene, có công thức cấu tạo CH₃–CH=CH₂. Propylene có tính chất hoá học tương tự ethylene vì có liên kết đôi C=C trong phân tử.
• Cháy: 2C₃H₆ + 9O₂ →(t°) 6CO₂ + 6H₂O
• Cộng bromine: CH₃–CH=CH₂ + Br₂ → CH₃–CHBr–CH₂Br
• Trùng hợp: nCH₃–CH=CH₂ →(t°, p, xúc tác) (–CH₂–CH(CH₃)–)ₙ (polypropylene, PP).', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.section = 'knowledge' and x.title = 'Câu hỏi SGK');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'experiment', 'text', 'Thí nghiệm: Điều chế và thử tính chất của ethylene (Hình 24.1)', 'Chuẩn bị: bình cầu có nhánh 250 mL đựng dung dịch cồn 96° và dung dịch H₂SO₄ đặc đã được trộn đều, đá bọt; ống nghiệm chứa khoảng 2 mL nước bromine; bình thuỷ tinh chứa dung dịch NaOH; ống dẫn thuỷ tinh đầu vuốt nhọn; ống dẫn thuỷ tinh hình chữ L.
Tiến hành: đun nóng bình cầu đến khi khí ethylene sinh ra và đi vào ống dẫn thuỷ tinh có đầu vuốt nhọn. Dùng que đóm đang cháy để đốt ethylene ở đầu vuốt nhọn của ống dẫn. Thay ống dẫn thuỷ tinh đầu vuốt nhọn bằng ống dẫn thuỷ tinh hình chữ L và dẫn khí ethylene vào ống nghiệm đựng nước bromine.
Kết quả: ở đầu ống dẫn vuốt nhọn, ethylene cháy được, toả nhiệt; ở ống nghiệm đựng nước bromine, nước bromine mất màu (màu vàng cam nhạt dần rồi mất màu). Nhận xét: ethylene có phản ứng cháy và phản ứng với nước bromine.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.section = 'experiment' and x.title = 'Thí nghiệm: Điều chế và thử tính chất của ethylene (Hình 24.1)');

-- Bài 25
update public.lessons set summary = 'Dầu mỏ, khí mỏ dầu và khí thiên nhiên là nhiên liệu hoá thạch có thành phần chính là hydrocarbon; nhiên liệu là chất cháy được, toả nhiệt và phát sáng, cần sử dụng an toàn, tiết kiệm.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'objective', 'Nêu được khái niệm, thành phần, trạng thái tự nhiên của dầu mỏ, khí thiên nhiên và khí mỏ dầu.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.content = 'Nêu được khái niệm, thành phần, trạng thái tự nhiên của dầu mỏ, khí thiên nhiên và khí mỏ dầu.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'objective', 'Trình bày được phương pháp khai thác dầu mỏ, khí thiên nhiên và khí mỏ dầu; một số sản phẩm chế biến từ dầu mỏ; ứng dụng của dầu mỏ và khí thiên nhiên (là nguồn nhiên liệu và nguyên liệu quý trong công nghiệp).', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.content = 'Trình bày được phương pháp khai thác dầu mỏ, khí thiên nhiên và khí mỏ dầu; một số sản phẩm chế biến từ dầu mỏ; ứng dụng của dầu mỏ và khí thiên nhiên (là nguồn nhiên liệu và nguyên liệu quý trong công nghiệp).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'objective', 'Nêu được khái niệm về nhiên liệu, các dạng nhiên liệu phổ biến (rắn, lỏng, khí).', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.content = 'Nêu được khái niệm về nhiên liệu, các dạng nhiên liệu phổ biến (rắn, lỏng, khí).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'objective', 'Trình bày được cách sử dụng nhiên liệu (gas, dầu hoả, than,...), từ đó có cách ứng xử thích hợp đối với việc sử dụng nhiên liệu trong cuộc sống.', 4 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.content = 'Trình bày được cách sử dụng nhiên liệu (gas, dầu hoả, than,...), từ đó có cách ứng xử thích hợp đối với việc sử dụng nhiên liệu trong cuộc sống.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'requirement', 'Sử dụng các loại nhiên liệu một cách tiết kiệm, hiệu quả, an toàn.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.content = 'Sử dụng các loại nhiên liệu một cách tiết kiệm, hiệu quả, an toàn.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'knowledge', 'text', '1. Dầu mỏ, khí mỏ dầu và khí thiên nhiên: khái niệm, thành phần, trạng thái tự nhiên', 'Dầu mỏ là nhiên liệu hoá thạch, có trong vỏ Trái Đất. Thành phần chính của dầu mỏ là các hydrocarbon. Thành phần dầu mỏ có thể khác nhau tuỳ thuộc vào vị trí mỏ dầu.
Trong tự nhiên, dầu mỏ thường tập trung thành những khu vực ở trong lòng đất, gọi là các mỏ dầu. Mỏ dầu thường có ba lớp (Hình 25.1):
• Lớp trên cùng là khí mỏ dầu (hay còn gọi là khí đồng hành). Khí mỏ dầu chứa chủ yếu là khí methane (khoảng 75%) và một số hydrocarbon khí khác.
• Lớp dầu lỏng có hoà tan khí và hỗn hợp phức tạp của nhiều loại hydrocarbon và một lượng nhỏ các hợp chất khác.
• Dưới đáy mỏ dầu là một lớp nước mặn.
Khí thiên nhiên cũng là nhiên liệu hoá thạch ở dưới lòng đất. Trong tự nhiên, khí thiên nhiên tập trung trong các mỏ khí dưới lòng đất hay rải rác thoát ra từ lớp bùn ở đáy ao. Thành phần chính của khí thiên nhiên là methane (khoảng 95%) và một số hydrocarbon khác như ethane, propane và butane. Trong khí thiên nhiên cũng có một lượng nhỏ carbon dioxide và nitrogen,...', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.section = 'knowledge' and x.title = '1. Dầu mỏ, khí mỏ dầu và khí thiên nhiên: khái niệm, thành phần, trạng thái tự nhiên');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'knowledge', 'text', '2. Phương pháp khai thác và chế biến', 'a) Dầu mỏ và khí mỏ dầu: khai thác dầu mỏ và khí mỏ dầu gồm nhiều giai đoạn: khoan, thu dầu và khí; loại bỏ tạp chất để thu dầu thô, vận chuyển đến nhà máy lọc dầu (bằng ống dẫn hoặc tàu chở dầu); tại nhà máy lọc dầu, dầu thô được xử lí chủ yếu bằng phương pháp chưng cất để thu được nhiều loại sản phẩm khác nhau ở các khoảng nhiệt độ khác nhau. Sau đó, dầu và khí sẽ được vận chuyển đến cơ sở sử dụng với các mục đích khác nhau (Bảng 25.1).
Ứng dụng của các sản phẩm chưng cất dầu mỏ (Bảng 25.1): khí hoá lỏng – nhiên liệu (sưởi ấm, bếp gas); dầu nhẹ – dung môi; naphtha nhẹ – dung môi; xăng – nhiên liệu cho động cơ đốt trong (xe máy, ô tô,...); dầu hoả – nhiên liệu cho động cơ phản lực; dầu diesel – nhiên liệu cho động cơ diesel và các lò nung; dầu bôi trơn – chất bôi trơn; sáp paraffin – sáp bóng, sáp dầu khoáng; nhựa đường – bề mặt đường, giấy dầu lợp mái.
b) Khí thiên nhiên: được khai thác bằng cách khoan xuống mỏ khí và khí sẽ tự phun lên do áp suất ở các mỏ khí lớn hơn áp suất khí quyển. Sau đó, khí được vận chuyển đến nhà máy để xử lí nhằm đạt được chất lượng mong muốn trước khi phân phối đến các điểm tiêu thụ khác nhau.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.section = 'knowledge' and x.title = '2. Phương pháp khai thác và chế biến');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'knowledge', 'text', '3. Nhiên liệu: khái niệm và phân loại', 'Nhiên liệu là những chất cháy được, khi cháy toả nhiệt và phát sáng. Nhiên liệu được phân loại dựa trên một số cơ sở khác nhau.
Dựa trên trạng thái tồn tại, nhiên liệu được phân loại thành nhiên liệu rắn (như gỗ, than mỏ), nhiên liệu lỏng (như xăng, dầu diesel, ethanol) và nhiên liệu khí (như hydrogen, methane, propane hay butane).', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.section = 'knowledge' and x.title = '3. Nhiên liệu: khái niệm và phân loại');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'knowledge', 'text', '4. Sử dụng nhiên liệu', 'Trong cuộc sống hằng ngày, các nhiên liệu như xăng, dầu hoả, gas hay than đáp ứng nhiều nhu cầu sử dụng của con người. Xe máy, ô tô và máy bay dùng nhiên liệu xăng và dầu hoả. Ở nhiều nơi trên thế giới, gas là nguồn nhiên liệu chính để sưởi ấm, nấu ăn, vận hành các thiết bị máy. Than là nhiên liệu quan trọng cho các nhà máy nhiệt điện, công nghiệp luyện kim.
Lựa chọn nhiên liệu phù hợp và sử dụng nhiên liệu một cách tiết kiệm, hiệu quả không chỉ mang lại nhiều lợi ích kinh tế mà còn góp phần bảo vệ môi trường. Vì vậy, cần tắt thiết bị khi không sử dụng, ưu tiên tham gia giao thông bằng phương tiện công cộng, bảo dưỡng xe thường xuyên để đảm bảo động cơ xe hoạt động hiệu quả và tiết kiệm nhiên liệu,...
Nhiên liệu là các chất dễ cháy, vì vậy việc sử dụng và lưu trữ nhiên liệu cần tuân thủ nghiêm ngặt các nguyên tắc về an toàn cháy nổ và hướng dẫn của nhà sản xuất. Xăng phải được bảo quản trong bình chứa đúng tiêu chuẩn. Bình gas cần được đặt nơi thông thoáng và cách xa nguồn nhiệt, đồng thời chúng ta nên thường xuyên kiểm tra để tránh rò rỉ. Không đốt cháy than, gas,... trong không gian kín, tránh nguy cơ ngộ độc khí.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.section = 'knowledge' and x.title = '4. Sử dụng nhiên liệu');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'knowledge', 'text', 'Em đã học', 'Dầu mỏ, khí mỏ dầu và khí thiên nhiên là nhiên liệu hoá thạch dưới bề mặt Trái Đất. Dầu mỏ gồm hỗn hợp của các hydrocarbon và hợp chất khác. Khí thiên nhiên có thành phần chính là methane (khoảng 95%) và ethane, propane, butane,... Phương pháp khai thác và chế biến: khoan, thu khí và dầu từ mỏ dầu, chưng cất dầu mỏ để thu được các sản phẩm khác nhau; khoan xuống mỏ khí thiên nhiên và thu khí. Nhiên liệu là những chất cháy được, khi cháy toả nhiệt và phát sáng. Nhiên liệu là các chất dễ cháy nên khi sử dụng cần tuân thủ nghiêm ngặt các biện pháp phòng cháy và chữa cháy. Trữ lượng nhiên liệu hoá thạch có hạn và việc sử dụng loại nhiên liệu này gây ô nhiễm môi trường, nên cần sử dụng tiết kiệm và hiệu quả.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.section = 'knowledge' and x.title = 'Em đã học');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'experiment', 'text', 'Hoạt động SGK 25: Mỏ dầu, nhiên liệu (bài này không có thí nghiệm thực hành)', 'SGK Bài 25 gồm các hoạt động quan sát hình, tìm hiểu thông tin và thảo luận, không có thí nghiệm thực hành.
• Hình 25.1 – sơ đồ cấu tạo mỏ dầu: lớp khí, lớp dầu, lớp nước mặn.
• Bảng 25.1 – ứng dụng các sản phẩm chưng cất dầu mỏ.
• Hình 25.2 – một số loại nhiên liệu phổ biến (gỗ, than đá, xăng, dầu diesel, xăng sinh học, khí thiên nhiên); trạng thái tồn tại của mỗi nhiên liệu ở điều kiện thường.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.section = 'experiment' and x.title = 'Hoạt động SGK 25: Mỏ dầu, nhiên liệu (bài này không có thí nghiệm thực hành)');

-- Bài 26
update public.lessons set summary = 'Ethylic alcohol (C₂H₅OH) là chất lỏng, tan vô hạn trong nước; nhóm –OH quyết định tính chất: cháy toả nhiệt, tác dụng với natri; được điều chế bằng lên men tinh bột hoặc cộng nước vào ethylene.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'objective', 'Viết được công thức phân tử, công thức cấu tạo và nêu được đặc điểm cấu tạo của ethylic alcohol.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.content = 'Viết được công thức phân tử, công thức cấu tạo và nêu được đặc điểm cấu tạo của ethylic alcohol.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'objective', 'Quan sát mẫu vật hoặc hình ảnh, trình bày được một số tính chất vật lí của ethylic alcohol: trạng thái, màu sắc, mùi vị, tính tan, khối lượng riêng, nhiệt độ sôi.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.content = 'Quan sát mẫu vật hoặc hình ảnh, trình bày được một số tính chất vật lí của ethylic alcohol: trạng thái, màu sắc, mùi vị, tính tan, khối lượng riêng, nhiệt độ sôi.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'objective', 'Nêu được khái niệm và ý nghĩa của độ cồn.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.content = 'Nêu được khái niệm và ý nghĩa của độ cồn.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'objective', 'Trình bày được tính chất hoá học của ethylic alcohol: phản ứng cháy, phản ứng với natri. Viết được các phương trình hoá học xảy ra.', 4 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.content = 'Trình bày được tính chất hoá học của ethylic alcohol: phản ứng cháy, phản ứng với natri. Viết được các phương trình hoá học xảy ra.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'objective', 'Tiến hành được (hoặc quan sát qua video) thí nghiệm phản ứng cháy, phản ứng với natri của ethylic alcohol, nêu và giải thích hiện tượng thí nghiệm, nhận xét và rút ra kết luận về tính chất hoá học cơ bản của ethylic alcohol.', 5 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.content = 'Tiến hành được (hoặc quan sát qua video) thí nghiệm phản ứng cháy, phản ứng với natri của ethylic alcohol, nêu và giải thích hiện tượng thí nghiệm, nhận xét và rút ra kết luận về tính chất hoá học cơ bản của ethylic alcohol.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'objective', 'Trình bày được phương pháp điều chế ethylic alcohol từ tinh bột và từ ethylene.', 6 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.content = 'Trình bày được phương pháp điều chế ethylic alcohol từ tinh bột và từ ethylene.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'objective', 'Nêu được ứng dụng của ethylic alcohol (dung môi, nhiên liệu,...).', 7 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.content = 'Nêu được ứng dụng của ethylic alcohol (dung môi, nhiên liệu,...).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'objective', 'Trình bày được tác hại của việc lạm dụng rượu bia.', 8 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.content = 'Trình bày được tác hại của việc lạm dụng rượu bia.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'requirement', 'Nhận biết được một số sản phẩm chứa ethylic alcohol trong đời sống.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.content = 'Nhận biết được một số sản phẩm chứa ethylic alcohol trong đời sống.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'requirement', 'Sử dụng nhiên liệu sinh học có chứa ethylic alcohol góp phần bảo vệ môi trường.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.content = 'Sử dụng nhiên liệu sinh học có chứa ethylic alcohol góp phần bảo vệ môi trường.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'requirement', 'Tránh lạm dụng các loại đồ uống có chứa cồn để bảo vệ sức khoẻ.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.content = 'Tránh lạm dụng các loại đồ uống có chứa cồn để bảo vệ sức khoẻ.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'knowledge', 'text', '1. Công thức và đặc điểm cấu tạo', 'Ethylic alcohol (ethanol) là hợp chất hữu cơ có công thức phân tử C₂H₆O. Công thức cấu tạo: CH₃–CH₂–OH.
Trong phân tử ethylic alcohol có nhóm –OH, đây là nhóm nguyên tử gây nên tính chất đặc trưng của ethylic alcohol.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.section = 'knowledge' and x.title = '1. Công thức và đặc điểm cấu tạo');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'knowledge', 'text', '2. Tính chất vật lí', 'Ethylic alcohol là chất lỏng, không màu, có mùi đặc trưng, vị cay, sôi ở 78,3 °C, có khối lượng riêng là 0,789 g/mL (ở 20 °C), tan vô hạn trong nước và hoà tan được nhiều chất như iodine, benzene,...
Độ cồn là số mililit ethylic alcohol nguyên chất có trong 100 mL dung dịch ở 20 °C. Độ cồn thường được kí hiệu là Xº hoặc X% vol. Ví dụ: cồn y tế 70° có nghĩa là trong 100 mL cồn 70° có chứa 70 mL ethylic alcohol nguyên chất.
Cồn y tế, nước rửa tay sát khuẩn,... chứa ethylic alcohol với hàm lượng từ 60% đến 85% vì thế có tính diệt khuẩn: khi tiếp xúc với vi khuẩn, ethylic alcohol gây đông tụ protein, phá vỡ cấu trúc của vi khuẩn, làm cho vi khuẩn chết.
Trên nhãn các chai bia, rượu vang, rượu whisky,… có ghi các giá trị như 4% vol, 14% vol, 40% vol,…: độ cồn của đồ uống.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.section = 'knowledge' and x.title = '2. Tính chất vật lí');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'knowledge', 'text', '3. Tính chất hoá học', 'a) Phản ứng cháy: ethylic alcohol dễ cháy trong không khí tạo thành carbon dioxide, hơi nước và toả nhiều nhiệt.
C₂H₅OH + 3O₂ →(t°) 2CO₂ + 3H₂O
Ứng dụng: ethylic alcohol được dùng làm nhiên liệu trong đèn cồn,... hoặc phối trộn với xăng làm nhiên liệu cho động cơ đốt trong (xe máy, ô tô,...) dựa vào tính chất cháy toả nhiều nhiệt.
b) Phản ứng với natri:
Thí nghiệm: cho khoảng 5 mL ethylic alcohol tuyệt đối vào ống nghiệm; dùng panh kẹp một mẩu natri bằng hạt ngô đưa vào ống nghiệm. Quan sát: mẩu natri tan dần, có khí thoát ra (bọt khí quanh mẩu natri). Cần làm sạch mẩu natri trước khi phản ứng; dùng panh kẹp mẩu natri, không dùng tay cầm trực tiếp.
2C₂H₅OH + 2Na → 2C₂H₅ONa + H₂
Các kim loại mạnh như Na, K thay thế được nguyên tử hydrogen trong nhóm –OH của ethylic alcohol, sản phẩm phản ứng có khí hydrogen được tạo thành.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.section = 'knowledge' and x.title = '3. Tính chất hoá học');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'knowledge', 'text', '4. Điều chế', 'a) Điều chế ethylic alcohol từ tinh bột: ethylic alcohol được điều chế bằng phương pháp lên men các nguyên liệu chứa tinh bột (gạo, ngô, sắn,...):
(C₆H₁₀O₅)ₙ →(+H₂O/enzyme) C₆H₁₂O₆ →(enzyme, −CO₂) C₂H₅OH   (tinh bột → glucose → ethylic alcohol)
Ngoài nguyên liệu giàu tinh bột, người ta còn sử dụng phụ phẩm của công nghiệp sản xuất đường (rỉ đường), nguyên liệu chứa cellulose (rơm, rạ, gỗ phế liệu,...) để sản xuất ethylic alcohol.
b) Điều chế ethylic alcohol từ ethylene: ethylic alcohol còn được điều chế bằng phản ứng cộng nước vào ethylene:
CH₂=CH₂ + H₂O →(t°, H⁺) C₂H₅OH
Phương pháp điều chế ethylic alcohol từ ethylene dùng để sản xuất ethylic alcohol trong công nghiệp.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.section = 'knowledge' and x.title = '4. Điều chế');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'knowledge', 'text', '5. Ứng dụng', 'Ethylic alcohol là một trong những hoá chất được sử dụng phổ biến trong công nghiệp và đời sống (Hình 26.5): làm dung môi trong mĩ phẩm, dược phẩm, vecni, sơn,...; sản xuất dung dịch sát khuẩn; sản xuất đồ uống có cồn (rượu); sản xuất nhiên liệu sinh học; điều chế acetic acid, ester.
Thành phần xăng sinh học: xăng thông thường và ethylic alcohol được phối trộn theo một tỉ lệ nhất định (thường từ 5% đến 20% ethylic alcohol về thể tích). Ví dụ: xăng E5 chứa 5% ethylic alcohol (về thể tích). Việc sử dụng xăng sinh học góp phần giảm bớt tỉ lệ tiêu thụ nhiên liệu hoá thạch, giảm lượng phát thải khí gây hiệu ứng nhà kính, giúp bảo vệ môi trường.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.section = 'knowledge' and x.title = '5. Ứng dụng');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'knowledge', 'text', '6. Tác hại của việc lạm dụng rượu, bia, đồ uống có cồn', 'Hiện nay, có nhiều loại đồ uống chứa cồn như rượu, bia, nước quả lên men,... Sử dụng quá nhiều đồ uống này sẽ tăng nguy cơ bị viêm gan, viêm loét dạ dày, tăng huyết áp, xơ vữa động mạch, gây tổn thương hệ thần kinh, rối loạn tâm thần. Việc lạm dụng rượu, bia là một trong những nguyên nhân gây tai nạn giao thông, tai nạn lao động, bạo lực trong mối quan hệ gia đình và xã hội. Học sinh không được sử dụng rượu, bia, đồ uống có cồn; người tham gia giao thông không uống rượu, bia khi lái xe.', 6, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.section = 'knowledge' and x.title = '6. Tác hại của việc lạm dụng rượu, bia, đồ uống có cồn');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'knowledge', 'example', 'Câu hỏi SGK', 'Trong các chất CH₃–CH₃; CH₂=CH₂; CH₃–OH; CH₃–CH₂–OH, chất tác dụng được với Na là CH₃–OH và CH₃–CH₂–OH (có nhóm –OH): 2CH₃OH + 2Na → 2CH₃ONa + H₂;  2C₂H₅OH + 2Na → 2C₂H₅ONa + H₂.', 7, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.section = 'knowledge' and x.title = 'Câu hỏi SGK');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'experiment', 'text', 'Thí nghiệm SGK: Phản ứng giữa natri và ethylic alcohol (Hình 26.4)', 'Chuẩn bị: ethylic alcohol tuyệt đối, kim loại natri, ống nghiệm, panh.
Tiến hành: cho khoảng 5 mL ethylic alcohol tuyệt đối vào ống nghiệm. Sau đó, dùng panh kẹp một mẩu natri bằng hạt ngô đưa vào ống nghiệm.
Quan sát: mẩu natri tan dần, có bọt khí thoát ra: 2C₂H₅OH + 2Na → 2C₂H₅ONa + H₂.
Lưu ý: cần làm sạch mẩu natri trước khi phản ứng; dùng panh kẹp mẩu natri, không dùng tay cầm trực tiếp.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK: Phản ứng giữa natri và ethylic alcohol (Hình 26.4)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'experiment', 'text', 'Thí nghiệm: Tìm hiểu về phản ứng cháy của ethylic alcohol', 'Chuẩn bị: ethylic alcohol (có thể dùng cồn 96°), bát sứ, que đóm.
Tiến hành: lấy khoảng 1 mL ethylic alcohol (chú ý không lấy nhiều hơn) cho vào bát sứ và dùng que đóm đang cháy để đốt ethylic alcohol.
Kết quả: ethylic alcohol cháy với ngọn lửa màu xanh nhạt, toả nhiều nhiệt (dấu hiệu: bát sứ và không khí xung quanh nóng lên). Khi đốt cháy, ethylic alcohol phản ứng với khí oxygen trong không khí tạo carbon dioxide và hơi nước.
Lưu ý: chỉ lấy một lượng nhỏ ethylic alcohol. Không được sử dụng diêm, bật lửa để đốt trực tiếp ethylic alcohol. Ethylic alcohol dễ bay hơi và dễ cháy nên cần hết sức chú ý khi sử dụng để tránh bị bỏng, hoả hoạn.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and x.section = 'experiment' and x.title = 'Thí nghiệm: Tìm hiểu về phản ứng cháy của ethylic alcohol');

-- Bài 27
update public.lessons set summary = 'Acetic acid (CH₃COOH) là acid yếu có đủ tính chất của một acid; tác dụng với ethylic alcohol tạo ester; được điều chế bằng lên men giấm từ ethylic alcohol loãng.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27), 'objective', 'Quan sát mô hình hoặc hình vẽ, viết được công thức phân tử, công thức cấu tạo; nêu được đặc điểm cấu tạo của acid acetic.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27) and x.content = 'Quan sát mô hình hoặc hình vẽ, viết được công thức phân tử, công thức cấu tạo; nêu được đặc điểm cấu tạo của acid acetic.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27), 'objective', 'Quan sát mẫu vật hoặc hình ảnh, trình bày được một số tính chất vật lí của acetic acid: trạng thái, màu sắc, mùi vị, tính tan, khối lượng riêng, nhiệt độ sôi.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27) and x.content = 'Quan sát mẫu vật hoặc hình ảnh, trình bày được một số tính chất vật lí của acetic acid: trạng thái, màu sắc, mùi vị, tính tan, khối lượng riêng, nhiệt độ sôi.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27), 'objective', 'Trình bày được phương pháp điều chế acetic acid bằng cách lên men ethylic alcohol.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27) and x.content = 'Trình bày được phương pháp điều chế acetic acid bằng cách lên men ethylic alcohol.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27), 'objective', 'Trình bày được tính chất hoá học của acetic acid: phản ứng với quỳ tím, đá vôi, kim loại, oxide kim loại, base, phản ứng cháy, phản ứng ester hoá. Viết được các phương trình hoá học xảy ra.', 4 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27) and x.content = 'Trình bày được tính chất hoá học của acetic acid: phản ứng với quỳ tím, đá vôi, kim loại, oxide kim loại, base, phản ứng cháy, phản ứng ester hoá. Viết được các phương trình hoá học xảy ra.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27), 'objective', 'Tiến hành được (hoặc quan sát qua video) thí nghiệm của acid acetic (phản ứng với quỳ tím, đá vôi, kim loại, oxide kim loại, base, phản ứng cháy, phản ứng ester hoá), nhận xét, rút ra được tính chất hoá học cơ bản của acetic acid.', 5 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27) and x.content = 'Tiến hành được (hoặc quan sát qua video) thí nghiệm của acid acetic (phản ứng với quỳ tím, đá vôi, kim loại, oxide kim loại, base, phản ứng cháy, phản ứng ester hoá), nhận xét, rút ra được tính chất hoá học cơ bản của acetic acid.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27), 'objective', 'Trình bày được ứng dụng của acetic acid (làm nguyên liệu, làm giấm).', 6 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27) and x.content = 'Trình bày được ứng dụng của acetic acid (làm nguyên liệu, làm giấm).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27), 'requirement', 'Biết cách tạo ra giấm bằng phương pháp lên men để sử dụng trong gia đình.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27) and x.content = 'Biết cách tạo ra giấm bằng phương pháp lên men để sử dụng trong gia đình.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27), 'requirement', 'Vận dụng các tính chất của acetic acid để ứng dụng trong đời sống như loại bỏ cặn trong ấm nước, thiết bị vệ sinh,...', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27) and x.content = 'Vận dụng các tính chất của acetic acid để ứng dụng trong đời sống như loại bỏ cặn trong ấm nước, thiết bị vệ sinh,...');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27), 'knowledge', 'text', '1. Công thức và đặc điểm cấu tạo', 'Acetic acid là hợp chất hữu cơ có công thức phân tử C₂H₄O₂. Công thức cấu tạo thu gọn: CH₃–COOH.
Trong phân tử acetic acid có nhóm –COOH, đây là nhóm nguyên tử gây nên tính chất đặc trưng của acetic acid. Nhóm –COOH gồm có nhóm –OH liên kết với nhóm C=O.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27) and x.section = 'knowledge' and x.title = '1. Công thức và đặc điểm cấu tạo');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27), 'knowledge', 'text', '2. Tính chất vật lí', 'Acetic acid là chất lỏng, không màu, vị chua, có mùi đặc trưng, sôi ở 118 °C, tan vô hạn trong nước, khối lượng riêng là 1,045 g/mL (ở 25 °C). Giấm ăn có chứa acetic acid với nồng độ thường từ 2% đến 5%.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27) and x.section = 'knowledge' and x.title = '2. Tính chất vật lí');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27), 'knowledge', 'text', '3. Tính chất hoá học', 'a) Tính acid: acetic acid là một acid yếu và có đầy đủ tính chất của một acid thông thường:
– Làm đổi màu chất chỉ thị acid như giấy quỳ (sang màu đỏ) và giấy chỉ thị pH.
– Phản ứng với kim loại giải phóng khí hydrogen: 2CH₃COOH + Mg → (CH₃COO)₂Mg + H₂
– Phản ứng với oxide kim loại tạo thành muối và nước: 2CH₃COOH + CuO → (CH₃COO)₂Cu + H₂O
– Phản ứng với base tạo muối và nước: CH₃COOH + NaOH → CH₃COONa + H₂O
– Phản ứng với muối carbonate, giải phóng khí carbon dioxide: 2CH₃COOH + CaCO₃ → (CH₃COO)₂Ca + CO₂ + H₂O
Ấm đun nước sử dụng một thời gian có lớp cặn (chứa CaCO₃) bám vào đáy và thành ấm; có thể loại bỏ lớp cặn này bằng giấm ăn.
b) Phản ứng ester hoá: acetic acid phản ứng với ethylic alcohol tạo thành ester và nước:
CH₃COOH + C₂H₅OH ⇌(H₂SO₄ đặc, t°) CH₃COOC₂H₅ + H₂O   (ethyl acetate)
Phản ứng giữa acetic acid và ethylic alcohol tạo ra ester (ethyl acetate) thuộc loại phản ứng ester hoá. Ethyl acetate là chất lỏng ở phía trên, không màu, có mùi thơm. Nhiều hợp chất ester dễ bay hơi, tạo nên mùi hương đặc trưng của nhiều loài hoa và các loại trái cây; được sử dụng làm hương liệu trong công nghiệp mĩ phẩm và thực phẩm.
c) Phản ứng cháy: acetic acid cháy trong khí oxygen tạo thành khí carbon dioxide và hơi nước:
CH₃COOH + 2O₂ →(t°) 2CO₂ + 2H₂O', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27) and x.section = 'knowledge' and x.title = '3. Tính chất hoá học');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27), 'knowledge', 'text', '4. Điều chế', 'Acetic acid dùng để sản xuất giấm được điều chế từ ethylic alcohol loãng bằng phương pháp lên men giấm:
C₂H₅OH + O₂ →(men giấm) CH₃COOH + H₂O
Khi để các loại rượu có độ cồn thấp (rượu vang, rượu mơ, rượu sâm panh,...) tiếp xúc với không khí, sau một thời gian thì các loại rượu này sẽ có vị chua do có phản ứng lên men giấm tạo acetic acid.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27) and x.section = 'knowledge' and x.title = '4. Điều chế');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27), 'knowledge', 'text', '5. Ứng dụng', 'Acetic acid là một trong những hoá chất được sử dụng phổ biến trong công nghiệp và đời sống (Hình 27.4). Acetic acid được sử dụng nhiều trong công nghiệp thực phẩm, dùng làm nguyên liệu đầu để sản xuất nhiều sản phẩm khác nhau như dược phẩm, phẩm nhuộm, tơ nhân tạo, chất dẻo,... (sản xuất tơ, dược phẩm, hoá chất, chất kết dính, giấm ăn, làm dung môi).', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27) and x.section = 'knowledge' and x.title = '5. Ứng dụng');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27), 'knowledge', 'example', 'Câu hỏi SGK', '• Chất có tính chất hoá học đặc trưng giống acetic acid: chất có nhóm –COOH, tức HCOOH (phương án C).
• Acetic acid tác dụng với các chất: Zn (2CH₃COOH + Zn → (CH₃COO)₂Zn + H₂); KOH (CH₃COOH + KOH → CH₃COOK + H₂O); ZnO (2CH₃COOH + ZnO → (CH₃COO)₂Zn + H₂O); MgCO₃ (2CH₃COOH + MgCO₃ → (CH₃COO)₂Mg + CO₂ + H₂O). Không tác dụng với NaCl và Cu.
• Propyl acetate: CH₃COOH + CH₃CH₂CH₂OH ⇌(H₂SO₄ đặc, t°) CH₃COOCH₂CH₂CH₃ + H₂O.', 6, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27) and x.section = 'knowledge' and x.title = 'Câu hỏi SGK');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27), 'experiment', 'text', 'Thí nghiệm: Tìm hiểu tính chất hoá học của acetic acid', 'Chuẩn bị: dung dịch acetic acid 10%, dung dịch NaOH 10%, Mg, CuO, đá vôi đập nhỏ, ống nghiệm, giấy quỳ tím (hoặc giấy chỉ thị pH), phenolphthalein, đèn cồn, ống hút nhỏ giọt.
Tiến hành và kết quả:
1. Với chất chỉ thị: nhỏ vài giọt dung dịch acetic acid lên mẫu giấy quỳ tím → giấy quỳ chuyển sang màu đỏ.
2. Với kim loại: cho một mảnh Mg vào ống nghiệm có khoảng 2 mL dung dịch acetic acid 10% → Mg tan dần, có khí không màu thoát ra (hydrogen).
3. Với oxide kim loại: cho vào ống nghiệm một ít bột CuO, nhỏ khoảng 2 mL dung dịch acetic acid, đun nhẹ → chất rắn màu đen tan dần, dung dịch chuyển sang màu xanh.
4. Với base: cho vào ống nghiệm 1 mL dung dịch NaOH 10%, thêm vài giọt phenolphthalein (dung dịch có màu hồng), nhỏ từ từ dung dịch acetic acid vào cho tới khi mất màu → màu hồng biến mất.
5. Với đá vôi: cho vào ống nghiệm khoảng 1 thìa thuỷ tinh đá vôi đập nhỏ, thêm khoảng 1 mL dung dịch acetic acid → có khí không màu thoát ra (carbon dioxide).', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27) and x.section = 'experiment' and x.title = 'Thí nghiệm: Tìm hiểu tính chất hoá học của acetic acid');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27), 'experiment', 'text', 'Thí nghiệm: Nghiên cứu phản ứng ester hoá giữa acetic acid và ethylic alcohol', 'Tiến hành: cho 2 mL ethylic alcohol và 2 mL acetic acid đặc vào ống nghiệm, lắc đều hỗn hợp. Thêm 1 mL dung dịch H₂SO₄ đặc, lắc nhẹ để các chất trộn đều với nhau. Kẹp ống nghiệm rồi đặt vào cốc nước nóng (khoảng 60 °C – 70 °C), thỉnh thoảng lắc ống nghiệm để trộn đều hỗn hợp. Sau khoảng 5 phút, để nguội hỗn hợp rồi đổ sang ống nghiệm khác chứa 5 mL dung dịch muối ăn bão hoà.
Kết quả: thấy xuất hiện lớp chất lỏng ở phía trên, không màu, có mùi thơm (ethyl acetate).
Chú ý: dung dịch H₂SO₄ đặc có thể gây bỏng nên cần cẩn thận khi sử dụng.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27) and x.section = 'experiment' and x.title = 'Thí nghiệm: Nghiên cứu phản ứng ester hoá giữa acetic acid và ethylic alcohol');

-- Bài 28
update public.lessons set summary = 'Lipid là hợp chất hữu cơ có trong tế bào sống, không tan trong nước; chất béo là triester của glycerol với acid béo, bị thuỷ phân trong môi trường kiềm tạo xà phòng.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28), 'objective', 'Nêu được khái niệm lipid, khái niệm chất béo, trạng thái thiên nhiên, công thức tổng quát của chất béo đơn giản là (R–COO)₃C₃H₅, đặc điểm cấu tạo.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28) and x.content = 'Nêu được khái niệm lipid, khái niệm chất béo, trạng thái thiên nhiên, công thức tổng quát của chất béo đơn giản là (R–COO)₃C₃H₅, đặc điểm cấu tạo.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28), 'objective', 'Trình bày được tính chất vật lí của chất béo (trạng thái, tính tan) và tính chất hoá học (phản ứng xà phòng hoá). Viết được phương trình hoá học xảy ra.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28) and x.content = 'Trình bày được tính chất vật lí của chất béo (trạng thái, tính tan) và tính chất hoá học (phản ứng xà phòng hoá). Viết được phương trình hoá học xảy ra.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28), 'objective', 'Nêu được vai trò của lipid tham gia cấu tạo tế bào và tích luỹ năng lượng trong cơ thể.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28) and x.content = 'Nêu được vai trò của lipid tham gia cấu tạo tế bào và tích luỹ năng lượng trong cơ thể.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28), 'objective', 'Trình bày được ứng dụng của chất béo và đề xuất biện pháp sử dụng chất béo cho phù hợp trong việc ăn uống hằng ngày để có cơ thể khoẻ mạnh, tránh được bệnh béo phì.', 4 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28) and x.content = 'Trình bày được ứng dụng của chất béo và đề xuất biện pháp sử dụng chất béo cho phù hợp trong việc ăn uống hằng ngày để có cơ thể khoẻ mạnh, tránh được bệnh béo phì.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28), 'requirement', 'Biết cách lựa chọn, sử dụng chất béo phù hợp trong ăn uống để có lợi cho sức khoẻ.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28) and x.content = 'Biết cách lựa chọn, sử dụng chất béo phù hợp trong ăn uống để có lợi cho sức khoẻ.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28), 'knowledge', 'text', '1. Lipid', 'Lipid là những hợp chất hữu cơ có trong tế bào sống, không tan trong nước, nhưng tan được trong một số dung môi hữu cơ như xăng, dầu hoả,...
Một số loại lipid điển hình là chất béo (nguồn dự trữ năng lượng chính trong cơ thể và là thành phần chính của dầu thực vật và mỡ động vật), sáp (thường được tìm thấy trên bề mặt lá, thân cây, trái cây của nhiều loại thực vật và da, lông của một số loài động vật, giúp chống mất nước và một số tác động có hại từ môi trường ngoài),...
Đặc trưng tính chất vật lí của lipid: không tan trong nước, tan trong dung môi hữu cơ. Lipid điển hình: chất béo (dự trữ năng lượng) và sáp (chống mất nước).', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28) and x.section = 'knowledge' and x.title = '1. Lipid');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28), 'knowledge', 'text', '2. Chất béo: khái niệm', 'Loại lipid được sử dụng phổ biến nhất trong cuộc sống hằng ngày là chất béo. Khi đun chất béo với nước, có mặt xúc tác acid hoặc enzyme lipase sẽ thu được glycerol và acid béo.
Glycerol là alcohol có công thức cấu tạo: CH₂(OH)–CH(OH)–CH₂(OH), viết gọn: C₃H₅(OH)₃.
Acid béo là các acid hữu cơ có công thức chung R–COOH, với R thường là –C₁₅H₃₁, –C₁₇H₃₅, –C₁₇H₃₃, –C₁₇H₃₁,... và thường có mạch carbon dài, không phân nhánh.
Từ kết quả trên, kết hợp với những phương pháp khác, người ta xác định được: chất béo là các triester (loại ester chứa 3 nhóm –COO– trong phân tử) của glycerol và acid béo, có công thức cấu tạo thu gọn là (RCOO)₃C₃H₅. R có thể giống nhau hoặc khác nhau.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28) and x.section = 'knowledge' and x.title = '2. Chất béo: khái niệm');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28), 'knowledge', 'text', '3. Tính chất vật lí của chất béo', 'Ở điều kiện thường, một số chất béo tồn tại ở trạng thái lỏng như dầu lạc, dầu hướng dương, dầu cọ,...; một số chất béo tồn tại ở trạng thái rắn như các loại mỡ động vật, bơ,...
Các chất béo nhẹ hơn nước, không tan trong nước và tan trong một số dung môi hữu cơ như benzene, xăng,...', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28) and x.section = 'knowledge' and x.title = '3. Tính chất vật lí của chất béo');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28), 'knowledge', 'text', '4. Tính chất hoá học: phản ứng xà phòng hoá', 'Chất béo có thể bị thuỷ phân hoàn toàn trong môi trường kiềm. Khi đun nóng chất béo với dung dịch NaOH (hoặc KOH), sản phẩm thu được là muối Na (hoặc K) của acid béo và glycerol.
Ví dụ: (RCOO)₃C₃H₅ + 3NaOH →(t°) 3RCOONa + C₃H₅(OH)₃
Muối Na (hoặc K) của các acid béo được sử dụng làm xà phòng nên loại phản ứng này có tên là phản ứng xà phòng hoá.
Làm xà phòng thủ công: để làm xà phòng, chất béo (dầu thực vật, mỡ động vật) được đun với dung dịch kiềm, khi đó muối natri của acid béo được tạo thành ở dạng keo. Các muối này được tách ra, sau đó trộn với các chất phụ gia, hương liệu, chất tạo màu,... rồi ép thành bánh.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28) and x.section = 'knowledge' and x.title = '4. Tính chất hoá học: phản ứng xà phòng hoá');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28), 'knowledge', 'text', '5. Ứng dụng và sử dụng chất béo đúng cách', 'Chất béo là một trong những thực phẩm thiết yếu của con người, được sử dụng dưới dạng dầu thực vật (như dầu hướng dương, đậu nành, lạc,...), mỡ động vật (như mỡ lợn, bò, cá,...), bơ, hoặc một số loại hạt (lạc, vừng, hạnh nhân, óc chó,...). Chất béo còn được dùng trong công nghiệp mĩ phẩm (chất làm mềm, dưỡng ẩm,...), dược phẩm, nhiên liệu (dầu diesel sinh học), nguyên liệu (sản xuất xà phòng),...
Sử dụng chất béo đúng cách để hạn chế béo phì: béo phì là tình trạng tích tụ mỡ quá mức trong cơ thể, là một trong những nguyên nhân gây ra nhiều bệnh khác nhau như bệnh tim mạch, đột quỵ, đái tháo đường, thoái hoá khớp, gan nhiễm mỡ,... Một trong những nguyên nhân gây bệnh béo phì là do chế độ ăn uống quá nhiều chất béo. Để hạn chế bệnh béo phì cần lưu ý lựa chọn thực phẩm có lượng chất béo phù hợp, ưu tiên sử dụng các chất béo có nguồn gốc thực vật, các chất béo giàu omega-3 (có trong cá hồi, hải sản), hạn chế sử dụng các chất béo có nguồn gốc động vật (mỡ lợn, mỡ bò,...) và các thức ăn đã qua chế biến ở nhiệt độ cao (thức ăn nhanh, đồ chiên, nướng,...).', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28) and x.section = 'knowledge' and x.title = '5. Ứng dụng và sử dụng chất béo đúng cách');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28), 'experiment', 'text', 'Hoạt động SGK 28: Chất béo và xà phòng (bài này không có thí nghiệm thực hành)', 'SGK Bài 28 gồm các hoạt động tìm hiểu thông tin, không có thí nghiệm thực hành.
• Hình 28.1: một số loại lipid – chất béo (dầu thực vật, mỡ động vật, bơ) và sáp (vỏ quả bơ, bề mặt lá cọ).
• Tìm hiểu và trình bày cách làm xà phòng từ dầu ăn, mỡ thừa sau khi sử dụng; liệt kê ba sản phẩm có chứa chất béo trong thành phần.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 28) and x.section = 'experiment' and x.title = 'Hoạt động SGK 28: Chất béo và xà phòng (bài này không có thí nghiệm thực hành)');

-- Bài 29
update public.lessons set summary = 'Carbohydrate là hợp chất hữu cơ chứa C, H, O thường có công thức Cₙ(H₂O)ₘ; glucose có phản ứng tráng bạc và lên men rượu, saccharose bị thuỷ phân tạo glucose và fructose.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29), 'objective', 'Nêu được thành phần nguyên tố, công thức chung của carbohydrate.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29) and x.content = 'Nêu được thành phần nguyên tố, công thức chung của carbohydrate.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29), 'objective', 'Nêu được công thức phân tử, trạng thái tự nhiên, tính chất vật lí (trạng thái, màu sắc, mùi, vị, tính tan, khối lượng riêng) của glucose và saccharose.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29) and x.content = 'Nêu được công thức phân tử, trạng thái tự nhiên, tính chất vật lí (trạng thái, màu sắc, mùi, vị, tính tan, khối lượng riêng) của glucose và saccharose.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29), 'objective', 'Trình bày được tính chất hoá học của glucose (phản ứng tráng bạc, phản ứng lên men rượu), của saccharose (phản ứng thuỷ phân có xúc tác acid hoặc enzyme). Viết được các phương trình hoá học xảy ra dưới dạng công thức phân tử.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29) and x.content = 'Trình bày được tính chất hoá học của glucose (phản ứng tráng bạc, phản ứng lên men rượu), của saccharose (phản ứng thuỷ phân có xúc tác acid hoặc enzyme). Viết được các phương trình hoá học xảy ra dưới dạng công thức phân tử.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29), 'objective', 'Tiến hành được thí nghiệm (hoặc quan sát thí nghiệm) phản ứng tráng bạc của glucose.', 4 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29) and x.content = 'Tiến hành được thí nghiệm (hoặc quan sát thí nghiệm) phản ứng tráng bạc của glucose.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29), 'objective', 'Trình bày được vai trò và ứng dụng của glucose (chất dinh dưỡng quan trọng của người và động vật) và của saccharose (nguyên liệu quan trọng trong công nghiệp thực phẩm). Ý thức được tầm quan trọng của việc sử dụng hợp lí saccharose. Nhận biết được các loại thực phẩm giàu saccharose và hoa quả giàu glucose.', 5 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29) and x.content = 'Trình bày được vai trò và ứng dụng của glucose (chất dinh dưỡng quan trọng của người và động vật) và của saccharose (nguyên liệu quan trọng trong công nghiệp thực phẩm). Ý thức được tầm quan trọng của việc sử dụng hợp lí saccharose. Nhận biết được các loại thực phẩm giàu saccharose và hoa quả giàu glucose.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29), 'requirement', 'Nêu được vai trò, ứng dụng của glucose, saccharose.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29) and x.content = 'Nêu được vai trò, ứng dụng của glucose, saccharose.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29), 'requirement', 'Nêu được tầm quan trọng của việc sử dụng hợp lí saccharose và ảnh hưởng của chúng đến sức khoẻ.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29) and x.content = 'Nêu được tầm quan trọng của việc sử dụng hợp lí saccharose và ảnh hưởng của chúng đến sức khoẻ.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29), 'knowledge', 'text', '1. Khái niệm carbohydrate', 'Carbohydrate là loại hợp chất hữu cơ chứa các nguyên tố carbon, hydrogen, oxygen, thường có công thức chung là Cₙ(H₂O)ₘ.
Một số carbohydrate (Hình 29.1): glucose C₆H₁₂O₆ (có nhiều trong quả nho chín); saccharose C₁₂H₂₂O₁₁ (có nhiều trong cây mía); tinh bột (C₆H₁₀O₅)ₙ (có nhiều trong gạo, ngô, khoai, sắn,...); cellulose (C₆H₁₀O₅)ₘ (có nhiều trong bông).
Glucose, saccharose, tinh bột và cellulose là những carbohydrate phổ biến trong tự nhiên và có nhiều ứng dụng trong cuộc sống hằng ngày.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29) and x.section = 'knowledge' and x.title = '1. Khái niệm carbohydrate');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29), 'knowledge', 'text', '2. Glucose và saccharose: trạng thái tự nhiên và tính chất vật lí', 'Glucose có công thức phân tử C₆H₁₂O₆, dạng tinh thể không màu (khối lượng riêng 1,56 g/cm³), không mùi, có vị ngọt. Glucose tan tốt trong nước. Glucose là loại đường có trong nhiều trái cây chín (đặc biệt nho chín). Glucose cũng có trong máu, đóng vai trò là nguồn năng lượng chính cho các hoạt động ở tế bào.
Saccharose có công thức phân tử C₁₂H₂₂O₁₁, dạng tinh thể không màu (khối lượng riêng 1,58 g/cm³), không mùi, có vị ngọt. Saccharose tan tốt trong nước. Saccharose là loại đường có nhiều trong mía, củ cải đường, thốt nốt.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29) and x.section = 'knowledge' and x.title = '2. Glucose và saccharose: trạng thái tự nhiên và tính chất vật lí');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29), 'knowledge', 'text', '3. Tính chất hoá học', 'a) Phản ứng tráng bạc của glucose: tính chất đặc trưng của glucose là có phản ứng hoá học với silver nitrate trong dung dịch ammonia tạo ra bạc kim loại. Phản ứng này được dùng để tráng bạc kim loại trong sản xuất gương soi, nên có tên là phản ứng tráng bạc.
C₆H₁₂O₆ + Ag₂O →(dung dịch NH₃, t°) C₆H₁₂O₇ + 2Ag
Saccharose không có phản ứng này.
b) Phản ứng lên men rượu của glucose: dưới tác dụng của enzyme, glucose bị lên men tạo thành ethylic alcohol. Phản ứng này được sử dụng để sản xuất bia, rượu hay các đồ uống có cồn khác.
C₆H₁₂O₆ →(enzyme) 2C₂H₅OH + 2CO₂
c) Phản ứng thuỷ phân của saccharose: phản ứng đặc trưng của saccharose là thuỷ phân (trong môi trường acid hoặc dưới tác dụng của enzyme) sinh ra glucose và fructose (một loại đường có công thức phân tử giống glucose nhưng khác công thức cấu tạo):
C₁₂H₂₂O₁₁ + H₂O →(enzyme hoặc acid, t°) C₆H₁₂O₆ (glucose) + C₆H₁₂O₆ (fructose)', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29) and x.section = 'knowledge' and x.title = '3. Tính chất hoá học');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29), 'knowledge', 'text', '4. Vai trò và ứng dụng', 'a) Vai trò: glucose hình thành ở thực vật qua quá trình quang hợp và ở động vật qua quá trình tiêu hoá carbohydrate. Glucose là nguồn năng lượng chính cho cả thực vật và động vật, cung cấp năng lượng cho các tế bào, hỗ trợ tăng trưởng và trao đổi chất. Saccharose có vai trò cung cấp năng lượng cho cơ thể nên được sử dụng phổ biến làm nguyên liệu trong công nghiệp thực phẩm. Tiêu thụ nhiều glucose, saccharose trong thời gian dài có nguy cơ bị béo phì và mắc các bệnh khác như tiểu đường, tim mạch,...
b) Ứng dụng: glucose được dùng làm nguyên liệu trong công nghiệp dược phẩm, thực phẩm. Ngoài ra, glucose cũng là nguyên liệu để sản xuất đồ uống có cồn và tráng gương (Hình 29.3). Saccharose được sử dụng làm chất tạo ngọt cho nhiều loại đồ uống và bánh kẹo.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29) and x.section = 'knowledge' and x.title = '4. Vai trò và ứng dụng');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29), 'experiment', 'text', 'Thí nghiệm: Phản ứng tráng bạc của glucose', 'Chuẩn bị: dung dịch glucose 10%, dung dịch AgNO₃ 1%, dung dịch NH₃ 5%, cốc nước nóng, ống nghiệm.
Tiến hành: cho khoảng 1 mL dung dịch AgNO₃ 1% vào ống nghiệm. Thêm từ từ dung dịch NH₃ 5% vào ống nghiệm và lắc đều đến khi kết tủa tan hoàn toàn. Cho khoảng 1 mL dung dịch glucose 10% vào ống nghiệm, lắc đều. Đặt ống nghiệm vào cốc đựng nước nóng (khoảng 70 – 80 °C), để yên khoảng 5 phút.
Kết quả: trên thành ống nghiệm xuất hiện lớp bạc kim loại sáng bóng như gương (phản ứng tráng bạc). Saccharose không có phản ứng này.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29) and x.section = 'experiment' and x.title = 'Thí nghiệm: Phản ứng tráng bạc của glucose');

-- Bài 30
update public.lessons set summary = 'Tinh bột và cellulose đều là carbohydrate (C₆H₁₀O₅)ₙ bị thuỷ phân hoàn toàn tạo glucose; hồ tinh bột hoá xanh tím với iodine còn cellulose thì không.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 30) and summary is null;
