update public.lessons set summary = 'Đá vôi (thành phần chính CaCO₃) được khai thác để làm vôi sống, vôi tôi, xi măng, thuỷ tinh; silicon và hợp chất silicate là nguyên liệu của công nghiệp gốm, sứ, thuỷ tinh, xi măng.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34) and summary is null;
