insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34), 'objective', 'Nêu được một số ứng dụng quan trọng của silicon và hợp chất của silicon.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34) and x.content = 'Nêu được một số ứng dụng quan trọng của silicon và hợp chất của silicon.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34), 'objective', 'Trình bày được sơ lược ngành công nghiệp silicate.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34) and x.content = 'Trình bày được sơ lược ngành công nghiệp silicate.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34), 'objective', 'Mô tả được các công đoạn chính sản xuất đồ gốm, thuỷ tinh, xi măng.', 4 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34) and x.content = 'Mô tả được các công đoạn chính sản xuất đồ gốm, thuỷ tinh, xi măng.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34), 'requirement', 'Đưa ra được ví dụ minh hoạ cho các ứng dụng quan trọng của silicon và các hợp chất của nó trong đời sống.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34) and x.content = 'Đưa ra được ví dụ minh hoạ cho các ứng dụng quan trọng của silicon và các hợp chất của nó trong đời sống.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34), 'requirement', 'Kể được tên các ngành sản xuất sử dụng nguyên liệu là đá vôi, đất sét, cát.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34) and x.content = 'Kể được tên các ngành sản xuất sử dụng nguyên liệu là đá vôi, đất sét, cát.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34), 'knowledge', 'text', '1. Khai thác đá vôi: nguồn đá vôi và thành phần chính', 'Đá vôi có nhiều ở vỏ Trái Đất, được tìm thấy ở những dãy núi đá, mỏ đá hay những bãi vỏ, xương động vật (san hô, vỏ ngao, ốc,...) ở ven biển (hoặc trước đây là ven biển). Ở nước ta, các dãy núi đá vôi tập trung nhiều ở các tỉnh thuộc Bắc Bộ và Bắc Trung Bộ.
Các bước chính khai thác đá vôi: khoan và nổ mìn (khoan lỗ vào đá và lấp đầy chúng bằng chất nổ, chất nổ sau đó được kích nổ, phá vỡ đá thành nhiều mảnh nhỏ hơn); bốc xếp và vận chuyển đá đến nhà máy; chế biến đá vôi (đá vôi được đập nhỏ và phân loại, sau đó được xử lí để sử dụng trong các ngành công nghiệp khác nhau). Việc khai thác đá vôi có thể gây ra các tác động đến môi trường, bao gồm xói mòn đất, ô nhiễm nước và phá huỷ môi trường sống; vì vậy cần được quy hoạch, cấp phép và thực hiện các biện pháp để giảm thiểu những tác động này.
Thành phần chính của đá vôi là calcium carbonate (CaCO₃). Calcium carbonate là chất rắn màu trắng, không tan trong nước. Đá vôi thường lẫn tạp chất nên có nhiều màu sắc khác nhau.
Em có biết: calcium carbonate tan dần trong nước có chứa khí carbon dioxide tạo ra muối tan là calcium hydrogen carbonate Ca(HCO₃)₂; vì vậy đá vôi trong tự nhiên bị bào mòn bởi nước mưa, tạo thành các hang động.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34) and x.section = 'knowledge' and x.title = '1. Khai thác đá vôi: nguồn đá vôi và thành phần chính');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34), 'knowledge', 'text', '2. Ứng dụng từ đá vôi', 'Đá vôi được sử dụng trong nhiều ngành như: xây dựng, công nghiệp, nông nghiệp.
a) Đá vôi nghiền: đá vôi được nghiền thành hạt nhỏ mịn, dùng làm chất độn cao su trong sản xuất săm lốp xe, chất độn trong sản xuất chất dẻo,...; được sử dụng nhiều trong công nghiệp thuỷ tinh, xi măng,...
b) Calcium oxide, calcium hydroxide: nung nóng đá vôi ở nhiệt độ cao xảy ra phản ứng phân huỷ tạo thành vôi sống (thành phần chính là calcium oxide): CaCO₃ →(t°) CaO + CO₂. Calcium oxide (CaO) là chất rắn, màu trắng, hút ẩm mạnh, phản ứng với nước tạo calcium hydroxide: CaO + H₂O → Ca(OH)₂. Calcium oxide được sử dụng làm nguyên liệu sản xuất thuỷ tinh, làm chất tạo xỉ trong luyện kim và còn được dùng trong xử lí nước thải, khử chua cho đất, khử trùng. Calcium hydroxide (Ca(OH)₂) là chất rắn, màu trắng, ít tan trong nước, tạo dung dịch base mạnh (gọi là nước vôi trong). Calcium hydroxide có nhiều ứng dụng như khử chua đất trồng, sản xuất clorua vôi dùng để tẩy trắng và khử trùng,...', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34) and x.section = 'knowledge' and x.title = '2. Ứng dụng từ đá vôi');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34), 'knowledge', 'text', '3. Công nghiệp silicate: silicon và hợp chất của silicon', 'Silicon là nguyên tố phổ biến thứ hai trong vỏ Trái Đất (chiếm 28,2% về khối lượng), chỉ sau oxygen.
Trong tự nhiên, silicon chỉ tồn tại ở dạng hợp chất, chủ yếu là oxide (SiO₂) có trong thạch anh, các loại cát, đất sét như cao lanh, mica,... hoặc muối silicate có trong đất sét, cao lanh, mica,... Các hợp chất và khoáng chất này được sử dụng làm nguyên liệu cho công nghiệp silicate, sản xuất gốm, sứ, thuỷ tinh, xi măng,...
Silicon tinh khiết là vật liệu bán dẫn, được sử dụng rộng rãi để chế tạo các vi mạch điện tử, thiết bị quang điện, cảm biến, pin Mặt Trời,... Thạch anh (SiO₂ gần nguyên chất) được sử dụng trong máy phát siêu âm, dụng cụ quang học, sản phẩm thuỷ tinh chịu nhiệt, sợi cáp quang,...', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34) and x.section = 'knowledge' and x.title = '3. Công nghiệp silicate: silicon và hợp chất của silicon');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34), 'knowledge', 'text', '4. Ngành công nghiệp silicate', 'Công nghiệp silicate bao gồm các ngành sản xuất đồ gốm, thuỷ tinh, xi măng.
a) Sản xuất đồ gốm: gạch ngói – nghiền, phối trộn nguyên liệu (đất sét, nước,...) thành khối dẻo; tạo hình; phơi (sấy) khô sản phẩm thô; nung sản phẩm thô trong lò ở nhiệt độ cao trong khoảng thời gian thích hợp. Đồ sứ – nghiền, phối trộn nguyên liệu (đất sét trắng, cát trắng, nước,...) thành khối dẻo; tạo hình; phơi (sấy) khô sản phẩm thô; nung sản phẩm thô lần thứ nhất trong lò ở nhiệt độ cao; tráng men, trang trí lên sản phẩm rồi nung lần hai.
Nước ta có nhiều nhà máy sản xuất gốm, sứ lớn ở Hà Nội, Hải Dương, Thành phố Hồ Chí Minh, Bình Dương, Đồng Nai,... và các làng nghề sản xuất gốm nổi tiếng như Bát Tràng (Hà Nội), Phù Lãng (Bắc Ninh), Thổ Hà (Bắc Giang), Thanh Hà (Hội An), Bàu Trúc (Ninh Thuận),...
b) Sản xuất thuỷ tinh: thuỷ tinh loại thông thường (được dùng làm cửa kính, chai lọ,...) là hỗn hợp của sodium silicate, calcium silicate. Thuỷ tinh loại này được sản xuất từ các nguyên liệu: cát thạch anh (cát trắng), đá vôi và soda (Na₂CO₃). Các công đoạn chính sản xuất thuỷ tinh: trộn hỗn hợp cát trắng, đá vôi, soda theo tỉ lệ thích hợp; nung hỗn hợp trong lò ở nhiệt độ cao khoảng 1 400 °C thành thuỷ tinh dạng nhão; làm nguội từ từ được thuỷ tinh dẻo, ép thổi thuỷ tinh dẻo thành các đồ vật.
CaCO₃ →(t°) CaO + CO₂;  CaO + SiO₂ →(t°) CaSiO₃;  Na₂CO₃ + SiO₂ →(t°) Na₂SiO₃ + CO₂
c) Sản xuất xi măng: xi măng là một loại vật liệu kết dính, được dùng trong xây dựng, đó là chất bột mịn, thường có màu lục xám. Xi măng được sản xuất bằng cách nghiền nhỏ đá vôi, trộn với đất sét có nhiều SiO₂ và một ít quặng sắt rồi nung hỗn hợp trong lò quay, hoặc lò đứng ở 1 400 – 1 600 °C. Sau khi nung, thu được hỗn hợp rắn, màu xám gọi là clanke (clinker). Nghiền clanke với thạch cao (CaSO₄·2H₂O) (khoảng 5%) và một số chất phụ gia khác thành bột mịn sẽ thu được xi măng.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34) and x.section = 'knowledge' and x.title = '4. Ngành công nghiệp silicate');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34), 'knowledge', 'text', 'Em đã học', 'Thành phần chính của đá vôi là CaCO₃. Đá vôi được dùng làm nguyên liệu sản xuất vôi, xi măng, thuỷ tinh, cao su, chất dẻo, gang,... Các hợp chất của silicon có trong cát, cao lanh, đất sét,... là nguyên liệu cho các ngành sản xuất gốm, sứ, thuỷ tinh, xi măng,... Silicon là vật liệu bán dẫn được sử dụng trong ngành công nghiệp điện tử.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34) and x.section = 'knowledge' and x.title = 'Em đã học');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34), 'experiment', 'text', 'Hoạt động SGK 34: Từ đá vôi đến vật liệu xây dựng (bài này không có thí nghiệm thực hành)', 'SGK Bài 34 gồm các câu hỏi và hoạt động tìm hiểu thông tin, không có thí nghiệm thực hành.
• Phản ứng nhiệt phân đá vôi và phản ứng vôi sống tác dụng với nước.
• Quan sát các vật dụng trong gia đình làm từ thuỷ tinh: vật dụng nào làm từ thuỷ tinh thường, vật dụng nào làm từ thuỷ tinh chịu nhiệt.
• Hình 34.2: các sản phẩm tạo thành trong quá trình sản xuất xi măng (clanke và xi măng).', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 34) and x.section = 'experiment' and x.title = 'Hoạt động SGK 34: Từ đá vôi đến vật liệu xây dựng (bài này không có thí nghiệm thực hành)');

-- Bài 35
update public.lessons set summary = 'Nhiên liệu hoá thạch (than, dầu mỏ, khí thiên nhiên) cung cấp phần lớn năng lượng nhưng cạn kiệt dần và thải ra CO₂, CH₄ gây hiệu ứng nhà kính, ấm lên toàn cầu; carbon luân chuyển trong chu trình carbon tự nhiên.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35) and summary is null;
