insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35), 'objective', 'Nêu được khí carbon dioxide và methane là nguyên nhân chính gây hiệu ứng nhà kính, sự ấm lên toàn cầu.', 7 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35) and x.content = 'Nêu được khí carbon dioxide và methane là nguyên nhân chính gây hiệu ứng nhà kính, sự ấm lên toàn cầu.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35), 'objective', 'Trình bày được những bằng chứng của biến đổi khí hậu, thời tiết do tác động của sự ấm lên toàn cầu; những dự đoán về các tác động tiêu cực trước mắt và lâu dài.', 8 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35) and x.content = 'Trình bày được những bằng chứng của biến đổi khí hậu, thời tiết do tác động của sự ấm lên toàn cầu; những dự đoán về các tác động tiêu cực trước mắt và lâu dài.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35), 'objective', 'Nêu được một số biện pháp giảm lượng khí thải carbon dioxide ở trong nước và ở phạm vi toàn cầu.', 9 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35) and x.content = 'Nêu được một số biện pháp giảm lượng khí thải carbon dioxide ở trong nước và ở phạm vi toàn cầu.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35), 'requirement', 'Vận động mọi người hạn chế sử dụng nhiên liệu hoá thạch (thay bếp than, gas bằng bếp điện, từ đi xe đạp, xe điện thay ô tô chạy xăng, dầu,...).', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35) and x.content = 'Vận động mọi người hạn chế sử dụng nhiên liệu hoá thạch (thay bếp than, gas bằng bếp điện, từ đi xe đạp, xe điện thay ô tô chạy xăng, dầu,...).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35), 'requirement', 'Trồng rừng và bảo vệ rừng.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35) and x.content = 'Trồng rừng và bảo vệ rừng.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35), 'knowledge', 'text', '1. Khái niệm nhiên liệu hoá thạch và nguồn gốc hình thành khí methane', 'Nhiên liệu hoá thạch là các loại nhiên liệu tự nhiên được tạo thành từ quá trình phân huỷ các sinh vật bị chôn vùi cách đây hàng trăm triệu năm. Các nhiên liệu này chứa hàm lượng carbon cao.
Nhiên liệu hoá thạch tồn tại ở thể rắn, lỏng và khí. Dạng rắn là than mỏ (than đá, than nâu, than bùn,...) chứa hàm lượng chính là carbon. Dạng lỏng là dầu mỏ, có thành phần chủ yếu là các hydrocarbon. Dạng khí chủ yếu là khí mỏ dầu và khí thiên nhiên (có hàm lượng methane lớn), băng cháy (khí tự nhiên đậm đặc ở áp suất cao trên 30 bar và nhiệt độ thấp dưới 0 °C).
Khí methane được hình thành từ các quá trình biến đổi sinh học và địa chất trong tự nhiên. Ngoài ra, một lượng lớn khí methane còn được sinh ra nhân tạo từ các hoạt động của con người như từ sự phân huỷ sinh học các chất hữu cơ trong các bãi rác thải, quá trình sản xuất nông nghiệp, tiêu hoá thức ăn của gia súc, sản xuất công nghiệp và các quá trình chế biến, chưng cất hay sản xuất khí mỏ dầu.
Theo số liệu thống kê của BP, cuối năm 2020, Việt Nam có trữ lượng có thể khai thác: than đá 3,36 tỉ tấn, dầu mỏ 4,4 tỉ thùng và khí thiên nhiên 600 tỉ m³.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35) and x.section = 'knowledge' and x.title = '1. Khái niệm nhiên liệu hoá thạch và nguồn gốc hình thành khí methane');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35), 'knowledge', 'text', '2. Khai thác và sử dụng nhiên liệu hoá thạch', 'Thực trạng khai thác: năng lượng hoá thạch là nguồn năng lượng chiếm tỉ lệ lớn nhất trong tổng các nguồn năng lượng khai thác hiện nay. Lượng nhiên liệu hoá thạch được khai thác và tiêu thụ hằng năm trên toàn cầu là rất lớn. Năm 2021, tổng lượng khai thác toàn cầu của dầu mỏ khoảng 95,70 triệu thùng/ngày, khí đốt tự nhiên khoảng 4,177 tỉ mét khối/ngày và than đá khoảng 7,7 tỉ tấn/năm. Năm 1986, tấn dầu mỏ đầu tiên được khai thác ở mỏ Bạch Hổ; năm 1987, Việt Nam bắt đầu xuất khẩu dầu thô.
Lợi ích: nhiên liệu hoá thạch mang lại cho con người rất nhiều lợi ích thiết thực trong cuộc sống. Nhiên liệu này có sẵn trong tự nhiên với trữ lượng lớn, quá trình khai thác dễ dàng và nhanh chóng. Nhiên liệu hoá thạch giữ vai trò rất lớn trong các cuộc cách mạng công nghiệp trên thế giới: than, dầu mỏ và khí thiên nhiên là nguồn nhiên liệu chính cho các nhà máy nhiệt điện, luyện kim, sản xuất xi măng, sản xuất hoá chất, giao thông vận tải,... Chúng đáp ứng được các nhu cầu đa dạng của con người: thắp sáng, sưởi ấm, nấu nướng, đi lại,...
Hạn chế: việc khai thác nhiên liệu hoá thạch với sản lượng lớn đang dẫn đến nguy cơ cạn kiệt nguồn tài nguyên. Mặt khác, quá trình đốt cháy nhiên liệu hoá thạch sinh ra một lượng lớn các chất thải như carbon dioxide, carbon monoxide, các oxide của lưu huỳnh, oxide của nitrogen,... tác động tiêu cực đến môi trường và sức khoẻ con người.
Giải pháp hạn chế sử dụng: thực hiện đồng bộ, tích cực và liên tục: tăng cường tiết kiệm nhiên liệu hoá thạch; tăng cường đi lại bằng phương tiện giao thông công cộng và xe điện; ưu tiên sử dụng xăng pha ethanol, sinh khối, biodiesel; sử dụng lại đồ dùng hay phân loại rác để có thể tái chế đồ dùng; sử dụng năng lượng tái tạo.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35) and x.section = 'knowledge' and x.title = '2. Khai thác và sử dụng nhiên liệu hoá thạch');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35), 'knowledge', 'text', '3. Nguồn carbon trong tự nhiên và chu trình carbon', 'Trạng thái tự nhiên của carbon: carbon có thể tồn tại ở dạng đơn chất (than chì, kim cương – Hình 35.1), dạng hợp chất vô cơ (carbon dioxide, muối carbonate,...), hợp chất hữu cơ (hydrocarbon, carbohydrate, protein,...).
Chu trình carbon trong tự nhiên: trong tự nhiên luôn có sự chuyển hoá carbon từ dạng này sang dạng khác. Sự chuyển hoá này diễn ra thường xuyên, liên tục và tạo thành chu trình khép kín (Hình 35.2). Chu trình carbon trong tự nhiên là một quá trình phức tạp, liên quan đến sự chuyển động và trao đổi carbon giữa khí quyển, đại dương, đất đai và các hệ sinh thái. Trong chu trình này, CO₂ đóng vai trò quan trọng trong việc duy trì sự cân bằng carbon trong hệ sinh thái và khí quyển của Trái Đất, thông qua các quá trình sau:
– Quá trình phát thải carbon ở dạng khí CO₂: CO₂ được chuyển vào khí quyển thông qua nhiều quá trình khác nhau như quá trình hô hấp của sinh vật, quá trình đốt cháy nhiên liệu hoá thạch, cháy rừng,...
– Quá trình hấp thụ carbon ở dạng khí CO₂: CO₂ được cây xanh sử dụng trong quá trình quang hợp để tạo ra các hợp chất hữu cơ. Các chất này sau đó được chuyển hoá thành hợp chất hữu cơ trong động vật khi động vật sử dụng thực vật làm nguồn dinh dưỡng. Khi thực vật, động vật bị vùi lấp, các hợp chất của carbon trong chúng phân huỷ thành muối carbonate, nhiên liệu hoá thạch,... Ngoài ra, CO₂ còn được hoà tan vào nước biển, sông, hồ,...', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35) and x.section = 'knowledge' and x.title = '3. Nguồn carbon trong tự nhiên và chu trình carbon');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35), 'knowledge', 'text', '4. Hiệu ứng nhà kính và sự ấm lên toàn cầu', 'Khí carbon dioxide và khí methane trong khí quyển tuy chiếm hàm lượng rất thấp nhưng lại là nguyên nhân chính gây ra hiệu ứng nhà kính trên Trái Đất. Trong thời đại công nghiệp (khoảng hơn 200 năm gần đây), hàm lượng carbon dioxide và methane trong khí quyển tăng dần, làm cho nhiệt độ trên bề mặt Trái Đất nóng lên.
Sự ấm lên toàn cầu diễn ra liên tục trong nhiều năm gần đây đã dẫn đến một số hệ quả:
– Thời tiết cực đoan: xuất hiện nhiều cơn bão lớn, lũ lụt và hạn hán kéo dài, gây thiệt hại cho mùa màng, nông sản.
– Băng tan, nước biển dâng: băng, tuyết ở các vùng cực và núi cao tan thành nước chảy ra biển, gây ra hiện tượng nước biển dâng; ngập lụt các khu vực đồng bằng, triều cường và xâm thực mặn, ảnh hưởng đến cuộc sống của hàng triệu người dân sống ở khu vực bờ biển.
– Sự acid hoá nước biển: lượng khí CO₂ tan trong nước biển tăng lên, ảnh hưởng tiêu cực đến môi trường sống của sinh vật biển.
– Thảm thực vật bị co hẹp, gia tăng tình trạng sa mạc hoá trên Trái Đất; giới động vật bị suy giảm tính đa dạng sinh học,...
Để giảm thiểu lượng khí thải carbon dioxide, Việt Nam và các quốc gia cùng thực hiện hạn chế sử dụng nhiên liệu hoá thạch, tăng cường sử dụng năng lượng tái tạo, áp dụng công nghệ tiên tiến trong xử lí rác thải, tăng cường trồng cây gây rừng, phủ xanh đồi trọc, cải tạo đất hoang,...
Từ năm 1901 đến năm 2020, hàm lượng CO₂ trong khí quyển tăng từ 0,030% đến 0,040% góp phần làm cho nhiệt độ Trái Đất tăng thêm 1,5 °C.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35) and x.section = 'knowledge' and x.title = '4. Hiệu ứng nhà kính và sự ấm lên toàn cầu');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35), 'knowledge', 'example', 'Bài tập SGK', '• Phương trình cháy: C₂H₅OH + 3O₂ →(t°) 2CO₂ + 3H₂O;  CH₄ + 2O₂ →(t°) CO₂ + 2H₂O;  C + O₂ →(t°) CO₂.
• Đốt cháy gỗ (15 – 20 kJ/g), than đá (20 – 30 kJ/g), dầu hoả (42 – 45 kJ/g): với cùng khối lượng, dầu hoả giải phóng nhiều nhiệt nhất.
• Củi gỗ không phải nhiên liệu hoá thạch vì không được hình thành từ xác sinh vật bị chôn vùi hàng triệu năm mà là sinh khối hiện tại.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35) and x.section = 'knowledge' and x.title = 'Bài tập SGK');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35), 'experiment', 'text', 'Hoạt động SGK 35: Số liệu khai thác dầu mỏ và chu trình carbon (bài này không có thí nghiệm thực hành)', 'SGK Bài 35 gồm các hoạt động đọc số liệu, quan sát hình và thảo luận, không có thí nghiệm thực hành.
• Bảng 35.1 – sản lượng khai thác dầu thô của thế giới từ năm 1988 đến năm 2016: 1988: 23,7; 1992: 24,5; 1996: 26,2; 2000: 28,2; 2004: 30,5; 2008: 31,8; 2012: 33,2; 2016: 35,4 (tỉ thùng) – vẽ đồ thị và nhận xét tốc độ gia tăng.
• Hình 35.2 – chu trình carbon trong tự nhiên và vai trò của carbon dioxide.
• Thảo luận các biện pháp giảm phát thải carbon dioxide ở phạm vi trong nước và toàn cầu.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 35) and x.section = 'experiment' and x.title = 'Hoạt động SGK 35: Số liệu khai thác dầu mỏ và chu trình carbon (bài này không có thí nghiệm thực hành)');


