insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('kinetic-potential', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'Động năng và thế năng của quả bóng', 'Thay đổi khối lượng, tốc độ, độ cao và quan sát động năng, thế năng thay đổi.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('mechanical-energy', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3), 'Bảo toàn cơ năng của con lắc', 'Quan sát sự chuyển hoá động năng – thế năng của con lắc, có và không có ma sát.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('work-power', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 4), 'Cần cẩu nâng hàng – Công và công suất', 'Nâng thùng hàng với khối lượng, độ cao và thời gian khác nhau để so sánh công và công suất.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('refraction', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5), 'Khúc xạ ánh sáng qua mặt phân cách', 'Thay đổi góc tới và cặp môi trường; đo góc khúc xạ và kiểm chứng định luật khúc xạ.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('total-reflection', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6), 'Phản xạ toàn phần và góc tới hạn', 'Chiếu ánh sáng từ môi trường chiết quang hơn ra môi trường kém chiết quang, tìm góc tới hạn.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('prism', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7), 'Đường truyền ánh sáng qua lăng kính', 'Quan sát tia sáng lệch về phía đáy và ánh sáng trắng bị tán sắc thành dải màu.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('lens', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8), 'Dựng ảnh qua thấu kính hội tụ và phân kì', 'Di chuyển vật, thay đổi tiêu cự; quan sát ba tia sáng đặc biệt và đặc điểm ảnh.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('focal-length', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9), 'Thực hành đo tiêu cự thấu kính hội tụ', 'Dịch vật và màn cách đều thấu kính đến khi ảnh rõ nét, cao bằng vật; tính f = L/4.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('magnifier', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10), 'Quan sát vật nhỏ qua kính lúp', 'Chọn kính lúp có số bội giác khác nhau, di chuyển vật để quan sát ảnh ảo phóng to.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('ohm-law', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11), 'Thí nghiệm định luật Ohm', 'Thay đổi hiệu điện thế nguồn, đo cường độ dòng điện; vẽ đồ thị I – U.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('series-parallel', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12), 'Đoạn mạch nối tiếp và song song', 'Tái hiện hai thí nghiệm SGK: nối tiếp (nguồn 12 V, R₁ = 6 Ω, R₂ = 10 Ω, R₃ = 16 Ω) và song song (nguồn 6 V, R₁ = 10 Ω, R₂ = 6 Ω).', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('electric-power', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13), 'Công suất điện và điện năng tiêu thụ', 'Bật các thiết bị trong gia đình, quan sát công suất, điện năng tiêu thụ và tiền điện.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('induction', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14), 'Cảm ứng điện từ – Máy phát điện xoay chiều', 'Các thí nghiệm SGK về cảm ứng điện từ: nam châm vĩnh cửu, nam châm điện, thay đổi tiết diện cuộn dây và mô hình máy phát điện xoay chiều.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('ac-effects', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'Các tác dụng của dòng điện xoay chiều', 'So sánh tác dụng nhiệt, phát sáng, từ (cuộn dây hút đinh sắt – SGK Hình 15.4) của dòng điện một chiều và xoay chiều.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('fossil-energy', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'Vòng năng lượng và đốt nhiên liệu hoá thạch', 'Đốt các loại nhiên liệu, tính nhiệt lượng toả ra và lượng khí CO₂ ước tính phát thải.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('renewable', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'Nhà máy điện năng lượng tái tạo', 'Mô phỏng pin Mặt Trời, tua-bin gió và thuỷ điện; thay đổi điều kiện tự nhiên và quan sát công suất.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('metal-reactions', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 18), 'Tính chất hoá học của kim loại', 'Tái hiện các thí nghiệm của SGK: kim loại tác dụng với oxygen, chlorine, lưu huỳnh, nước, dung dịch HCl và dung dịch muối.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('activity-series', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 19), 'Xây dựng và sử dụng dãy hoạt động hoá học', 'Làm lại các thí nghiệm của SGK (nước, dung dịch HCl, dung dịch AgNO₃) để sắp xếp mức độ hoạt động hoá học của kim loại; đối chiếu với dãy hoạt động.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('metal-extraction', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20), 'Phương pháp tách kim loại theo mức độ hoạt động', 'Chọn nhóm kim loại và xem phương pháp tách phù hợp: điện phân nóng chảy, nhiệt luyện hoặc thuỷ luyện, kèm phương trình hoá học.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('charcoal-adsorption', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21), 'Tính hấp phụ của than gỗ', 'Rót nước màu qua phễu có bột than gỗ và quan sát sự mất màu – tính hấp phụ của carbon.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('alkane-combustion', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'Phản ứng cháy của alkane', 'Đốt butane (và các alkane C1 – C4), thử sản phẩm bằng thành bình khô và nước vôi trong; so sánh nhiệt lượng toả ra.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('ethylene', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'Tính chất hoá học của ethylene', 'Đốt ethylene, dẫn ethylene vào nước bromine và quan sát phản ứng trùng hợp; so sánh với propylene.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('ethanol', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26), 'Tính chất hoá học của ethylic alcohol', 'Đốt ethylic alcohol, cho natri tác dụng với ethylic alcohol; so sánh với methyl alcohol.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('acetic-acid', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 27), 'Tính chất hoá học của acetic acid', 'Acetic acid với quỳ tím, Mg, CuO, NaOH, CaCO₃, phản ứng ester hoá với ethylic alcohol và phản ứng cháy.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('glucose-saccharose', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 29), 'Tính chất hoá học của glucose và saccharose', 'Phản ứng tráng bạc và lên men rượu của glucose; phản ứng thuỷ phân của saccharose.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('starch-cellulose', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 30), 'Tính chất của tinh bột và cellulose', 'Phản ứng màu của hồ tinh bột với iodine; thuỷ phân tinh bột và cellulose.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
insert into public.experiments (key, lesson_id, title, summary, sort_order) values ('protein', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 31), 'Tính chất của protein', 'Lòng trắng trứng với acid, nhiệt độ, đun nóng mạnh; đốt thử sợi vải để phân biệt tơ tự nhiên với tơ nylon.', 1) on conflict (key) do update set lesson_id = excluded.lesson_id, title = excluded.title, summary = excluded.summary;
